const areas = [
  'Bishan','Bukit Merah','Bukit Timah','Downtown Core','Geylang','Kallang',
  'Marina East','Marina South','Marine Parade','Museum','Newton','Novena',
  'Orchard','Outram','Queenstown','River Valley','Rochor','Singapore River',
  'Southern Islands','Straits View','Tanglin','Toa Payoh','Bedok','Changi',
  'Changi Bay','Pasir Ris','Paya Lebar','Tampines','Central Water Catchment',
  'Lim Chu Kang','Mandai','Sembawang','Simpang','Sungei Kadut','Woodlands',
  'Yishun','Ang Mo Kio','Hougang','North-Eastern Islands','Punggol','Seletar',
  'Sengkang','Serangoon','Boon Lay','Bukit Batok','Bukit Panjang',
  'Choa Chu Kang','Clementi','Jurong East','Jurong West','Pioneer','Tengah',
  'Tuas','Western Islands','Western Water Catchment'
];

const categories = [
  { q: 'GP clinic', batch: 'Batch 1 - Sep 2027' },
  { q: 'acute hospital', batch: 'Batch 1 - Sep 2027' },
  { q: 'community hospital', batch: 'Batch 1 - Sep 2027' },
  { q: 'clinical laboratory', batch: 'Batch 1 - Sep 2027' },
  { q: 'radiology centre', batch: 'Batch 1 - Sep 2027' },
  { q: 'nuclear medicine service', batch: 'Batch 1 - Sep 2027' },
  { q: 'specialist outpatient clinic', batch: 'Batch 2 - Sep 2028' },
  { q: 'nursing home', batch: 'Batch 2 - Sep 2028' },
  { q: 'contingency care service', batch: 'Batch 2 - Sep 2028' },
  { q: 'dialysis centre', batch: 'Batch 2 - Sep 2028' },
  { q: 'ambulatory surgical centre', batch: 'Batch 3 - Mar 2030' },
  { q: 'dental clinic', batch: 'Batch 3 - Mar 2030' },
  { q: 'assisted reproduction centre', batch: 'Batch 3 - Mar 2030' },
  { q: 'retail pharmacy', batch: 'Batch 3 - Mar 2030' }
];

const combos = [];
for (const cat of categories) {
  for (const area of areas) {
    combos.push({
      search_query: cat.q + ' ' + area + ' Singapore',
      category: cat.q,
      hia_batch: cat.batch,
      area,
    });
  }
}

for (const vendorQuery of [
  'healthcare IT Singapore',
  'medical software Singapore',
  'HIMS Singapore',
  'EMR software Singapore',
  'clinic management system Singapore',
  'medical records software Singapore',
  'telemedicine platform Singapore'
]) {
  combos.push({
    search_query: vendorQuery,
    category: vendorQuery,
    hia_batch: 'Vendor to HIA clients',
    area: 'Singapore',
  });
}

return combos.map((combo) => ({ json: combo }));

const combos = $('Generate Search Combos').all();
const placeItems = $('Serper Places').all();
const organicItems = $('Serper Organic Fallback').all();
const now = new Date().toISOString();

const BLOCKED_HOSTS = [
  'facebook.com','linkedin.com','instagram.com','healthhub.sg','moh.gov.sg','yellowpages.com.sg',
  'wherecrowded.sg','gobusiness.gov.sg','acra.gov.sg','recordowl.com','findhealthclinics.com',
  'locallead.ai','contact.page','yelp.com','tripadvisor.com','foursquare.com','classpcn.sg','pcds.sg',
  'doctorxdentist.com','practo.com'
];
const BLOCKED_PATH_PATTERNS = ['/listing/','/review/','/venue/','/directory/','/map/','/locations/'];
const BLOCKED_TEXT_PATTERNS = [
  'primary care network','healthier sg','government of singapore','singapore government',
  'primary care digital services','ministry of health','health hub'
];

function normalizeText(value) {
  return String(value || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim();
}

function normalizeUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = withProtocol.match(/^(https?:\/\/)([^/?#]+)([^?#]*)/i);
  if (!match) return '';
  const hostname = String(match[2] || '').replace(/^www\./i, '').toLowerCase().trim();
  if (!hostname || !hostname.includes('.')) return '';
  return 'https://' + hostname + '/';
}

function extractDomain(value) {
  const homepage = normalizeUrl(value);
  const match = homepage.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  return String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
}

function allowedCandidate(name, url, text) {
  const domain = extractDomain(url);
  if (!name || !domain) return false;
  if (BLOCKED_HOSTS.some((host) => domain === host || domain.endsWith('.' + host))) return false;
  if (BLOCKED_PATH_PATTERNS.some((pattern) => String(url || '').toLowerCase().includes(pattern))) return false;
  const haystack = normalizeText([name, text, domain].join(' '));
  if (BLOCKED_TEXT_PATTERNS.some((pattern) => haystack.includes(pattern))) return false;
  return true;
}

function cleanOrganicTitle(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  return raw
    .replace(/\s+[|\-–—]\s+Singapore.*$/i, '')
    .replace(/\s+[|\-–—]\s+Official.*$/i, '')
    .replace(/\s+[|\-–—]\s+Home.*$/i, '')
    .trim() || raw;
}

const seenDomains = new Set();
const seedRows = [];

for (let index = 0; index < combos.length; index += 1) {
  const combo = combos[index]?.json || {};
  const placePayload = placeItems[index]?.json || {};
  const organicPayload = organicItems[index]?.json || {};
  const places = Array.isArray(placePayload.places) ? placePayload.places : [];
  const organic = Array.isArray(organicPayload.organic)
    ? organicPayload.organic
    : Array.isArray(organicPayload.results)
      ? organicPayload.results
      : [];
  const comboSeen = new Set();

  for (const place of places) {
    const companyName = String(place.title || '').trim();
    const homepage = normalizeUrl(place.website || place.link || '');
    const domain = extractDomain(homepage);
    const summary = [place.category || '', place.address || '', place.description || ''].join(' ');
    if (!allowedCandidate(companyName, homepage, summary)) continue;
    if (comboSeen.has(domain) || seenDomains.has(domain)) continue;
    comboSeen.add(domain);
    seenDomains.add(domain);
    seedRows.push({
      json: {
        company_name: companyName,
        candidate_homepage: homepage,
        candidate_domain: domain,
        category: String(combo.category || '').trim(),
        hia_batch: String(combo.hia_batch || '').trim(),
        area: String(combo.area || '').trim(),
        status: 'pending',
        discovered_at: now,
      },
    });
  }

  if (comboSeen.size >= 4) continue;
  for (const item of organic) {
    if (comboSeen.size >= 4) break;
    const companyName = cleanOrganicTitle(item.title || '');
    const homepage = normalizeUrl(item.link || item.url || '');
    const domain = extractDomain(homepage);
    const summary = [item.snippet || '', item.content || ''].join(' ');
    if (!allowedCandidate(companyName, homepage, summary)) continue;
    if (comboSeen.has(domain) || seenDomains.has(domain)) continue;
    comboSeen.add(domain);
    seenDomains.add(domain);
    seedRows.push({
      json: {
        company_name: companyName,
        candidate_homepage: homepage,
        candidate_domain: domain,
        category: String(combo.category || '').trim(),
        hia_batch: String(combo.hia_batch || '').trim(),
        area: String(combo.area || '').trim(),
        status: 'pending',
        discovered_at: now,
      },
    });
  }
}

return seedRows.length ? seedRows : [{ json: { _skip: true, rows: [] } }];

function normalizeName(value) {
  return String(value || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, ' ').trim();
}
function normalizeUrl(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  const withProtocol = /^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : 'https://' + raw;
  const match = withProtocol.match(/^(?:https?:\/\/)?([^/?#]+)/i);
  const hostname = String(match?.[1] || '').replace(/^www\./i, '').toLowerCase().trim();
  return hostname && hostname.includes('.') ? hostname : '';
}

const incoming = $('Normalize Seed Rows').all().filter((item) => !item.json._skip);
const existing = (($input.first() || {}).json || {}).list || [];
const seenDomains = new Set();
const seenNames = new Set();

for (const row of existing) {
  const domain = normalizeUrl(row.url_validated || row.best_url || '');
  const name = normalizeName(row.company_name || '');
  if (domain) seenDomains.add(domain);
  if (name) seenNames.add(name);
}

const batchDomains = new Set();
const batchNames = new Set();
const rows = [];

for (const item of incoming) {
  const row = item.json || {};
  const domain = normalizeUrl(row.candidate_domain || row.candidate_homepage || '');
  const name = normalizeName(row.company_name || '');
  if (!domain && !name) continue;
  if ((domain && (seenDomains.has(domain) || batchDomains.has(domain))) || (name && !domain && (seenNames.has(name) || batchNames.has(name)))) continue;
  if (domain) batchDomains.add(domain);
  if (name) batchNames.add(name);
  rows.push({ json: row });
}

return rows.length ? rows : [{ json: { _skip: true } }];

const rows = $input.all().map((item) => item.json).filter((row) => !row._skip);
if (!rows.length) return [{ json: { rows: [] } }];
const payloadRows = rows.map((row) => ({
  company_name: row.company_name,
  hia_batch: row.hia_batch || '',
  status: 'pending'
}));
const chunks = [];
for (let index = 0; index < payloadRows.length; index += 100) {
  chunks.push({ json: { rows: payloadRows.slice(index, index + 100) } });
}
return chunks;
